"""The sound catalogue for the API: ids and names from static/catalog_data.js (generated by scripts/make_catalog.mjs,
the same list the front end uses), facts read from each WAV (header, peak, RMS), licence, and the compressed copies.
"""
import json
import threading
from functools import lru_cache
from pathlib import Path

from .analysis import file_levels

ROOT = Path(__file__).resolve().parent.parent
CATALOG_JS = ROOT / "static" / "catalog_data.js"
FORMATS = {"wav": ("", "audio/wav"), "opus": (".opus", "audio/ogg"), "m4a": (".m4a", "audio/mp4")}
LICENCES = {
    "original": {"key": "MIT", "text": "Original sound, synthesised by scripts/synth_sounds.py; MIT licence (LICENSE)."},
    "third-party": {"key": "royalty-free", "text": "Korg DS-8 Sci-Fi Sound Effects Pack, Copyright (c) 2008 Zeta Centauri, "
                    "Inc.; royalty-free use (audio/Korg-DS-8-Sci-Fi-Sound-Effects-Pack/Readme.txt, THIRD_PARTY.md)."},
}
_lock = threading.Lock()


@lru_cache(maxsize=1)
def entries() -> tuple[dict, ...]:
    """Catalogue rows (id, file, name, cat, origin, how, ...) parsed from the generated JS module."""
    rows = []
    for line in CATALOG_JS.read_text().splitlines():
        line = line.strip().rstrip(",")
        if line.startswith("{"):
            rows.append(json.loads(line))
    return tuple(rows)


def by_id(sound_id: str) -> dict | None:
    return next((e for e in entries() if e["id"] == sound_id), None)


def path_for(entry: dict, fmt: str = "wav") -> Path:
    """Path of a sound's file in a format (wav, opus, m4a); the copies sit next to the WAV."""
    wav = ROOT / entry["file"]
    return wav if fmt == "wav" else wav.with_suffix(FORMATS[fmt][0])


_levels: dict = {}


def facts(entry: dict) -> dict:
    """Header facts and levels of one WAV, cached by (path, size, mtime)."""
    p = path_for(entry)
    st = p.stat()
    key = (str(p), st.st_size, st.st_mtime_ns)
    with _lock:
        if key not in _levels:
            _levels[key] = file_levels(p)
        return _levels[key]


def describe(entry: dict) -> dict:
    """One sound for /api/sounds: catalogue fields, facts from the file, licence, available formats and sizes."""
    f = facts(entry)
    files = {fmt: path_for(entry, fmt) for fmt in FORMATS}
    return {
        "id": entry["id"], "name": entry["name"], "category": entry["cat"], "source": entry["source"],
        "origin": entry["origin"], "how": entry.get("how"), "file": entry["file"],
        "duration": round(f["duration"], 4), "rate": f["rate"], "channels": f["channels"], "bits": f["bits"],
        "frames": f["frames"], "peak_db": round(f["peak_db"], 2), "rms_db": round(f["rms_db"], 2),
        "licence": LICENCES[entry["origin"]]["key"], "licence_text": LICENCES[entry["origin"]]["text"],
        "formats": {k: p.stat().st_size for k, p in files.items() if p.exists()},
    }


def all_sounds() -> list[dict]:
    return [describe(e) for e in entries()]
